SELECT DATE_TRUNC('MONTH', start_date) AS start_month, plan, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count FROM subscriptions WHERE plan IN ('basic', 'premium', 'standard') OR customer_id IN (3, 20, 26) GROUP BY DATE_TRUNC('MONTH', start_date), plan HAVING COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) < 2
